package com.tekwatt.reservation.controller;import com.tekwatt.reservation.dto.*;import com.tekwatt.reservation.service.ReservationService;import jakarta.validation.Valid;import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/v1/reservations")public class ReservationController{private final ReservationService service;public ReservationController(ReservationService s){service=s;}@PostMapping @ResponseStatus(HttpStatus.CREATED)ReservationResponse create(@Valid@RequestBody ReservationRequest r){return service.create(r);}@GetMapping("/{id}")ReservationResponse get(@PathVariable UUID id){return service.get(id);}@GetMapping List<ReservationResponse>list(@RequestParam UUID tenantId){return service.list(tenantId);}@PostMapping("/{id}/cancel")ReservationResponse cancel(@PathVariable UUID id){return service.cancel(id);}@PostMapping("/{id}/complete")ReservationResponse complete(@PathVariable UUID id){return service.complete(id);}}
